// MARK: - Grouping

struct InvoiceMonth: Identifiable {
    let id: Date
    let title: String
    let invoices: [Invoice]
}

extension InvoiceMonth {
    static func group(_ invoices: [Invoice], calendar: Calendar = .current) -> [InvoiceMonth] {
        let grouped = Dictionary(grouping: invoices) { invoice in
            calendar.date(
                from: calendar.dateComponents([.year, .month], from: invoice.issuedAt)
            ) ?? invoice.issuedAt
        }

        return grouped.keys
            .sorted(by: >)
            .map { month in
                InvoiceMonth(
                    id: month,
                    title: month.formatted(.dateTime.month(.wide).year()),
                    invoices: (grouped[month] ?? []).sorted { $0.issuedAt > $1.issuedAt }
                )
            }
    }
}

