@MainActor
@Observable
final class InvoiceListViewModel {
    enum ViewState {
        case loading
        case loaded([InvoiceMonth])
        case empty
        case failed(String)
    }

    private(set) var state: ViewState = .loading

    private let repository: any InvoiceRepository
    private let calendar: Calendar

    init(repository: any InvoiceRepository, calendar: Calendar = .current) {
        self.repository = repository
        self.calendar = calendar
    }

    func loadIfNeeded() async {
        guard case .loading = state else { return }
        await fetch()
    }

    func refresh() async {
        await fetch()
    }

    func retry() async {
        state = .loading
        await fetch()
    }

    private func fetch() async {
        do {
            let invoices = try await repository.fetchInvoices()
            let months = InvoiceMonth.group(invoices, calendar: calendar)
            state = months.isEmpty ? .empty : .loaded(months)
        } catch is CancellationError {
            return
        } catch {
            if case .loaded = state { return }
            state = .failed("We couldn't load your invoices. Check your connection and try again.")
        }
    }
}

