        let grouped = Dictionary(grouping: invoices) { invoice in
            calendar.date(
                from: calendar.dateComponents([.year, .month], from: invoice.issueDate)
            ) ?? invoice.issueDate
        }

        return grouped
            .map { month, invoices in
                InvoiceMonthSection(
                    id: month,
                    month: month,
                    invoices: invoices.sorted { $0.issueDate > $1.issueDate }
                )
            }
            .sorted { $0.month > $1.month }
    }

    var showsInitialLoading: Bool {
        isLoading && !hasLoaded
    }

    var isEmpty: Bool {
        hasLoaded && invoices.isEmpty && errorMessage == nil
    }

    func loadIfNeeded() async {
        guard !hasLoaded else { return }
        await load()
    }

    func refresh() async {
        await load()
    }

    func dismissError() {
        errorMessage = nil
    }

    private func load() async {
        guard !isLoading else { return }
        isLoading = true
        defer { isLoading = false }

        do {
            invoices = try await service.fetchInvoices()
            errorMessage = nil
        } catch is CancellationError {
            return
        } catch {
            errorMessage = error.localizedDescription
        }

        hasLoaded = true
    }
}

