            ScrollView {
                ContentUnavailableView {
                    Label("Couldn't load invoices", systemImage: "exclamationmark.triangle")
                } description: {
                    Text(error)
                } actions: {
                    Button("Try Again") {
                        Task { await viewModel.refresh() }
                    }
                    .buttonStyle(.borderedProminent)
                }
                .frame(maxWidth: .infinity, minHeight: 320)
            }
            .scrollBounceBehavior(.always)
            .refreshable {
                await viewModel.refresh()
            }
        } else if viewModel.isEmpty {
            ScrollView {
                ContentUnavailableView(
                    "No invoices",
                    systemImage: "doc.text",
                    description: Text("New invoices will appear here.")
                )
                .frame(maxWidth: .infinity, minHeight: 320)
            }
            .scrollBounceBehavior(.always)
            .refreshable {
                await viewModel.refresh()
            }
        } else {
            invoiceList
        }
    }

    private var invoiceList: some View {
        List {
            ForEach(viewModel.sections) { section in
                Section(section.title) {
                    ForEach(section.invoices) { invoice in
                        NavigationLink(value: invoice) {
                            InvoiceRow(invoice: invoice)
                        }
                    }
                }
            }
        }
        .listStyle(.insetGrouped)
        .refreshable {
            await viewModel.refresh()
        }
    }

    private var refreshErrorBinding: Binding<Bool> {
        Binding(
            get: { viewModel.errorMessage != nil && !viewModel.invoices.isEmpty },
            set: { isPresented in
                if !isPresented {
                    viewModel.dismissError()
                }
            }
        )
    }
}

