Key points:

- `@Observable` + `@MainActor` view model keeps UI mutations on the main actor while `InvoiceService` does the async work.
- `.refreshable` drives pull-to-refresh; `.task` loads once on first appearance.
- Loading, error, empty, and populated states are distinct.
- `NavigationStack` + `navigationDestination` provides typed navigation to the detail screen.
- Semantic fonts, `.fixedSize(vertical:)`, and an accessibility-size layout switch keep rows usable at large Dynamic Type sizes.
- Status is conveyed by text and symbol as well as colour, so it does not rely on colour alone.

Inject `RemoteInvoiceService` at app composition instead of the preview service for production.

```python
#!/usr/bin/env python3
import json
import random
import time
from pathlib import Path
from urllib.parse import urljoin

from playwright.sync_api import (
    Page,
    TimeoutError as PlaywrightTimeoutError,
    sync_playwright,
)

START_URL = "https://example.com/jobs"
OUTPUT_FILE = Path("jobs.json")
POLITE_DELAY_SECONDS = 1.5
NAV_TIMEOUT_MS = 30_000
MAX_PAGES = 100


def dismiss_cookie_banner(page: Page) -> None:
    button = page.get_by_role("button", name="Accept")
    if not button.count():
        button = page.locator(".cookie-banner button")
    if not button.count():
        return
    try:
        button.first.click(timeout=3_000)
        page.locator(".cookie-banner").wait_for(state="hidden", timeout=3_000)
    except PlaywrightTimeoutError:
        pass


def wait_for_jobs(page: Page) -> None:
    page.locator("#jobs").wait_for(state="visible", timeout=NAV_TIMEOUT_MS)
    try:
        page.locator("#jobs li.job").first.wait_for(state="visible", timeout=5_000)
    except PlaywrightTimeoutError:
        pass


def goto_with_retry(page: Page, url: str, attempts: int = 3) -> None:
    for attempt in range(1, attempts + 1):
        try:
            page.goto(url, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
            wait_for_jobs(page)
            return
        except PlaywrightTimeoutError:
            if attempt == attempts:
                raise
            time.sleep(POLITE_DELAY_SECONDS * attempt)


def text_or_empty(scope, selector: str) -> str:
    locator = scope.locator(selector)
    return locator.first.inner_text().strip() if locator.count() else ""


def scrape_page(page: Page) -> list[dict]:
    jobs = []
    for card in page.locator("#jobs li.job").all():
        title_link = card.locator("a.title")
        href = title_link.get_attribute("href") or ""
        jobs.append(
            {
                "title": title_link.inner_text().strip(),
                "company": text_or_empty(card, ".company"),
                "location": text_or_empty(card, ".location"),
                "url": urljoin(page.url, href) if href else "",
            }
        )
    return jobs


def next_page_url(page: Page) -> str | None:
    link = page.locator('a[rel="next"]')
    if not link.count() or not link.first.is_visible():
        return None
    href = link.first.get_attribute("href")
    return urljoin(page.url, href) if href else None


def scrape_all(page: Page) -> list[dict]:
    jobs: list[dict] = []
    seen_urls: set[str] = set()
    seen_pages: set[str] = set()
    url: str | None = START_URL

    for _ in range(MAX_PAGES):
        if not url or url in seen_pages:
            break
        seen_pages.add(url)

        goto_with_retry(page, url)
        dismiss_cookie_banner(page)

        for job in scrape_page(page):
            key = job["url"] or f'{job["title"]}|{job["company"]}|{job["location"]}'
            if key not in seen_urls:
                seen_urls.add(key)
                jobs.append(job)

        url = next_page_url(page)
        if url:
            time.sleep(POLITE_DELAY_SECONDS + random.uniform(0, 0.5))

    return jobs


def save_jobs(jobs: list[dict]) -> None:
    payload = json.dumps(jobs, indent=2, ensure_ascii=False)
    tmp = OUTPUT_FILE.with_suffix(OUTPUT_FILE.suffix + ".tmp")
    tmp.write_text(payload, encoding="utf-8")
    tmp.replace(OUTPUT_FILE)


def main() -> None:
    try:
        with sync_playwright() as pw:
            browser = pw.chromium.launch(headless=True)
            try:
                context = browser.new_context()
                try:
                    page = context.new_page()
                    page.set_default_timeout(NAV_TIMEOUT_MS)
                    jobs = scrape_all(page)
                finally:
                    context.close()
            finally:
                browser.close()
    except PlaywrightTimeoutError as exc:
        raise SystemExit(f"Timed out while scraping: {exc}") from exc
    except Exception as exc:
        raise SystemExit(f"Scraping failed: {exc}") from exc

    save_jobs(jobs)
    print(f"Saved {len(jobs)} jobs to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()
```

Notes:
- Install with `pip install playwright && playwright install chromium`.
- Cookie dismissal uses a role-based locator first (`get_by_role("button", name="Accept")`) with a CSS fallback, per the Playwright skill's selector priority.
- Waits are locator-based (no arbitrary `wait_for_timeout`); the `time.sleep` between pages is the intentional polite delay.
- `seen_pages` prevents pagination loops, `seen_urls` deduplicates results, `MAX_PAGES` caps runaway pagination, and JSON is written atomically.
